// Types + helpers for the SAT question bank in static/sat (generated by scripts/extract_sat.py)

export type Img = { src: string; w: number; h: number };
export type Letter = 'A' | 'B' | 'C' | 'D';

export type Question = {
	id: string;
	domain: string;
	skill: string;
	difficulty: string;
	type: 'mcq' | 'spr';
	stem: Img;
	stemText: string;
	choices: Record<Letter, Img> | null;
	answer: Letter | null;
	acceptedAnswers: string[] | null;
	rationale: Img;
	rationaleText: string;
};

export type Progress = Record<string, { tries: number; right: number; last: boolean; flagged?: boolean }>;

export const LETTERS: Letter[] = ['A', 'B', 'C', 'D'];
export const imgUrl = (img: Img) => `/sat/${img.src}`;

/** Parse "3/2", "-.5", "1.5", "+4" → number (NaN if not a number). */
export function parseNumber(raw: string): number {
	const s = raw.replace(/\s+/g, '').replace(/^\+/, '').replace(/[−–]/g, '-');
	const frac = s.match(/^(-?\d*\.?\d+)\/(-?\d*\.?\d+)$/);
	if (frac) return Number(frac[1]) / Number(frac[2]);
	return /^-?(\d+\.?\d*|\.\d+)$/.test(s) ? Number(s) : NaN;
}

/** Student-produced response check: exact match or numeric match against any accepted answer. */
export function checkSpr(input: string, accepted: string[]): boolean {
	const s = input.replace(/\s+/g, '');
	if (!s) return false;
	if (accepted.includes(s)) return true;
	const v = parseNumber(s);
	if (Number.isNaN(v)) return false;
	return accepted.some((a) => {
		const t = parseNumber(a);
		return !Number.isNaN(t) && Math.abs(t - v) < 1e-9;
	});
}

const KEY = 'sat-progress-v1';
export function loadProgress(): Progress {
	try {
		return JSON.parse(localStorage.getItem(KEY) ?? '{}');
	} catch {
		return {};
	}
}
export function saveProgress(p: Progress) {
	try {
		localStorage.setItem(KEY, JSON.stringify(p));
	} catch {
		/* storage unavailable — progress just won't persist */
	}
}

export function shuffle<T>(arr: T[]): T[] {
	const a = [...arr];
	for (let i = a.length - 1; i > 0; i--) {
		const j = Math.floor(Math.random() * (i + 1));
		[a[i], a[j]] = [a[j], a[i]];
	}
	return a;
}
